import { useMemo, useState } from 'react'
import { AlertTriangle, CheckCircle2, CircleDashed, GitCompare, Radio, ShieldAlert, TrendingDown, TrendingUp } from 'lucide-react'

export type AssuranceState = 'new' | 'changed' | 'resolved' | 'regressed' | 'stable'
export type AssuranceCheckpoint = { id: string; label: string; timestamp: string; state: AssuranceState; risk: number; previousRisk?: number; confidence: number; sources: number; critical: number; blastRadius: number }

export function ContinuousAssuranceFabric({ checkpoints, onSelect, onOpenPosture, onOpenExecutive }: { checkpoints: AssuranceCheckpoint[]; onSelect?: (checkpoint: AssuranceCheckpoint) => void; onOpenPosture?: () => void; onOpenExecutive?: () => void }) {
  const [selectedId, setSelectedId] = useState(checkpoints[checkpoints.length - 1]?.id ?? null)
  const selected = checkpoints.find((c) => c.id === selectedId) ?? checkpoints[checkpoints.length - 1]
  const summary = useMemo(() => ({
    newCount: checkpoints.filter((c) => c.state === 'new').length,
    changedCount: checkpoints.filter((c) => c.state === 'changed').length,
    resolvedCount: checkpoints.filter((c) => c.state === 'resolved').length,
    regressedCount: checkpoints.filter((c) => c.state === 'regressed').length,
  }), [checkpoints])
  const pick = (checkpoint: AssuranceCheckpoint) => { setSelectedId(checkpoint.id); onSelect?.(checkpoint) }

  if (!checkpoints.length) return <section className="rounded-2xl border bg-card p-8 text-center"><CircleDashed className="mx-auto h-8 w-8 text-muted-foreground" /><h3 className="mt-3 text-sm font-semibold">No assurance checkpoints</h3><p className="mt-1 text-xs text-muted-foreground">New validation checkpoints will appear here when assurance signals are available.</p></section>

  return <section className="overflow-hidden rounded-2xl border bg-card"><header className="flex flex-wrap items-center justify-between gap-4 border-b px-5 py-4"><div><div className="flex items-center gap-2 font-semibold"><Radio className="h-4 w-4 text-primary" /> Continuous Assurance Fabric</div><p className="mt-1 text-xs text-muted-foreground">Detect change, regression, and recovery across independent security signals.</p></div><div className="flex gap-2"><button type="button" onClick={onOpenPosture} className="rounded-lg border px-3 py-2 text-xs font-semibold hover:bg-muted">View posture</button><button type="button" onClick={onOpenExecutive} className="rounded-lg bg-primary px-3 py-2 text-xs font-semibold text-primary-foreground">Executive impact</button></div></header><div className="grid grid-cols-2 gap-px border-b bg-border md:grid-cols-4">{[['New', summary.newCount], ['Changed', summary.changedCount], ['Resolved', summary.resolvedCount], ['Regressed', summary.regressedCount]].map(([label, value]) => <div key={String(label)} className="bg-card p-4"><div className="text-[10px] uppercase tracking-wider text-muted-foreground">{label}</div><div className="mt-1 text-2xl font-black">{value}</div></div>)}</div><div className="grid lg:grid-cols-[minmax(0,1fr)_340px]"><div className="divide-y">{checkpoints.map((checkpoint) => <button key={checkpoint.id} type="button" onClick={() => pick(checkpoint)} aria-pressed={checkpoint.id === selected.id} className={`flex w-full items-center gap-3 px-5 py-4 text-left transition hover:bg-muted/30 ${checkpoint.id === selected.id ? 'bg-primary/5' : ''}`}><span className="grid h-9 w-9 place-items-center rounded-lg border bg-background">{iconForState(checkpoint.state)}</span><span className="min-w-0 flex-1"><span className="block text-xs font-semibold">{checkpoint.label}</span><span className="mt-1 block text-[10px] text-muted-foreground">{checkpoint.timestamp} · {checkpoint.sources} sources · {checkpoint.confidence}% confidence</span></span><span className="text-right"><span className="block text-sm font-bold">{checkpoint.risk}</span><span className="text-[9px] uppercase tracking-wide text-muted-foreground">risk</span></span></button>)}</div><aside className="border-t bg-muted/10 p-5 lg:border-l lg:border-t-0"><div className="text-[10px] font-semibold uppercase tracking-[0.14em] text-muted-foreground">Assurance delta</div><h3 className="mt-2 font-semibold">{selected.label}</h3><div className="mt-4 grid grid-cols-2 gap-2"><Metric label="Risk" value={selected.risk} /><Metric label="Confidence" value={`${selected.confidence}%`} /><Metric label="Critical" value={selected.critical} /><Metric label="Blast" value={selected.blastRadius} /></div>{selected.previousRisk !== undefined && <div className="mt-4 rounded-xl border bg-background p-3"><div className="text-[9px] uppercase tracking-wider text-muted-foreground">Change from previous</div><div className={`mt-1 flex items-center gap-2 text-xl font-black ${selected.risk <= selected.previousRisk ? 'text-emerald-600' : 'text-destructive'}`}>{selected.risk <= selected.previousRisk ? <TrendingDown className="h-4 w-4" /> : <TrendingUp className="h-4 w-4" />} {selected.risk - selected.previousRisk > 0 ? '+' : ''}{selected.risk - selected.previousRisk}</div></div>}<div className="mt-4 flex items-center gap-2 rounded-xl border bg-background p-3 text-[10px]"><GitCompare className="h-4 w-4 text-primary" /> Delta is propagated to posture and executive decision surfaces.</div></aside></div></section>
}
function iconForState(state: AssuranceState) { if (state === 'resolved') return <CheckCircle2 className="h-4 w-4 text-emerald-600" />; if (state === 'regressed') return <AlertTriangle className="h-4 w-4 text-destructive" />; if (state === 'changed') return <GitCompare className="h-4 w-4 text-primary" />; return <ShieldAlert className="h-4 w-4 text-amber-600" /> }
function Metric({ label, value }: { label: string; value: string | number }) { return <div className="rounded-lg border bg-background px-3 py-2"><div className="text-[9px] uppercase tracking-wider text-muted-foreground">{label}</div><div className="mt-1 text-lg font-bold">{value}</div></div> }
